import re

def parse(lines):
    blocks = []
    skip = []
    rows = []
    rl = []
    flags = {}
    fl = []
    pend = None
    for i, l in enumerate(lines):
        s = l.rstrip()
        if not s.strip():
            continue
        if s.startswith('Flags:'):
            for m in re.finditer(r'(\S+) - ([^,]+)', s[6:]):
                flags[m.group(1)] = m.group(2).strip()
            fl.append(i)
            continue
        if re.match(r'^\s*#\s+ADDRESS', s):
            skip.append(i)
            continue
        m = re.match(r'^\s*(?P<idx>\d+)\s+(?P<flags>[A-Z]*)\s*;;;\s*(?P<c>.*)$', s)
        if m:
            pend = {'idx': m.group('idx'), 'flags': m.group('flags'), 'comment': m.group('c').strip(), 'lines': [i]}
            continue
        m = re.match(r'^\s*(?:(?P<idx>\d+)\s+(?P<flags>[A-Z]*)\s+)?(?P<addr>\S+/\d+)\s+(?P<net>\S+)\s+(?P<iface>\S+)\s*$', s)
        if m:
            if m.group('idx') is None and pend is not None:
                idx = pend['idx']
                fg = pend['flags']
                cm = pend['comment']
                rl.extend(pend['lines'])
            else:
                idx = m.group('idx') or ''
                fg = m.group('flags') or ''
                cm = ''
            pend = None
            rows.append({'#': idx, 'FLAGS': fg, 'ADDRESS': m.group('addr'), 'NETWORK': m.group('net'), 'INTERFACE': m.group('iface'), 'COMMENT': cm})
            rl.append(i)
            continue
    if fl:
        blocks.append({'name': 'flags', 'kind': 'kv', 'lines': fl, 'records': [flags]})
    if rows:
        blocks.append({'name': 'addresses', 'kind': 'table', 'lines': sorted(rl), 'records': rows})
    return {'blocks': blocks, 'skip': skip}
